import java.io.IOException;
import java.nio.ByteBuffer;
import java.nio.channels.FileChannel;
import java.nio.file.Path;
import java.nio.file.StandardOpenOption;

public class Solution {

    public record Stats(long lines, long errorLines, long totalLatency,
                        long maxLineBytes, long bytesRead) {
    }

    private static final byte[] ERROR = {'E', 'R', 'R', 'O', 'R'};

    public static Stats analyze(Path file, int bufferSize) throws IOException {
        if (file == null) {
            throw new IllegalArgumentException("file não pode ser nulo");
        }
        if (bufferSize < 16) {
            throw new IllegalArgumentException("bufferSize deve ser >= 16");
        }

        Parser parser = new Parser();
        try (FileChannel channel = FileChannel.open(file, StandardOpenOption.READ)) {
            ByteBuffer buffer = ByteBuffer.allocateDirect(bufferSize);
            while (channel.read(buffer) != -1) {
                buffer.flip();
                while (buffer.hasRemaining()) {
                    parser.accept(buffer.get());
                }
                buffer.clear();
            }
        }
        return parser.finish();
    }

    private static final class Parser {
        private long lines;
        private long errorLines;
        private long totalLatency;
        private long maxLineBytes;
        private long bytesRead;

        private int field;
        private long lineBytes;
        private long latency;
        private boolean hasDigits;
        private boolean levelIsError;
        private boolean levelError;
        private int errorIndex;

        void accept(byte b) {
            bytesRead++;
            if (b == '\r') {
                return;
            }
            if (b == '\n') {
                endLine();
                return;
            }
            lineBytes++;
            if (b == ',') {
                if (field == 0) {
                    field = 1;
                    levelIsError = true;
                    errorIndex = 0;
                } else if (field == 1) {
                    levelError = levelIsError && errorIndex == ERROR.length;
                    field = 2;
                }
                return;
            }
            if (field == 1) {
                if (levelIsError) {
                    if (errorIndex < ERROR.length && b == ERROR[errorIndex]) {
                        errorIndex++;
                    } else {
                        levelIsError = false;
                    }
                }
            } else if (field == 2 && b >= '0' && b <= '9') {
                latency = latency * 10 + (b - '0');
                hasDigits = true;
            }
        }

        Stats finish() {
            if (lineBytes > 0) {
                endLine();
            }
            return new Stats(lines, errorLines, totalLatency, maxLineBytes, bytesRead);
        }

        private void endLine() {
            if (lineBytes > 0) {
                lines++;
                if (field == 2 && hasDigits) {
                    totalLatency += latency;
                }
                if (levelError || (field == 1 && levelIsError && errorIndex == ERROR.length)) {
                    errorLines++;
                }
                if (lineBytes > maxLineBytes) {
                    maxLineBytes = lineBytes;
                }
            }
            field = 0;
            lineBytes = 0;
            latency = 0;
            hasDigits = false;
            levelIsError = false;
            levelError = false;
            errorIndex = 0;
        }
    }
}

