import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;

class SolutionTest {

    @TempDir
    Path tempDir;

    private Path write(String content) throws IOException {
        Path file = tempDir.resolve("log-" + Math.abs(content.hashCode()) + ".csv");
        Files.writeString(file, content, StandardCharsets.US_ASCII);
        return file;
    }

    @Test
    void contaLinhasErrosELatencias() throws IOException {
        Path file = write("1,INFO,10\n2,ERROR,25\n3,ERROR,5\n");
        Solution.Stats stats = Solution.analyze(file, 16);

        assertEquals(3, stats.lines());
        assertEquals(2, stats.errorLines());
        assertEquals(40, stats.totalLatency());
        assertEquals(10, stats.maxLineBytes());
        assertEquals(Files.size(file), stats.bytesRead());
    }

    @Test
    void ultimaLinhaSemTerminadorEhContada() throws IOException {
        Path file = write("1,INFO,7");
        Solution.Stats stats = Solution.analyze(file, 16);

        assertEquals(1, stats.lines());
        assertEquals(7, stats.totalLatency());
        assertEquals(0, stats.errorLines());
        assertEquals(8, stats.maxLineBytes());
    }

    @Test
    void aceitaCrlf() throws IOException {
        Path file = write("1,INFO,10\r\n2,ERROR,20\r\n");
        Solution.Stats stats = Solution.analyze(file, 16);

        assertEquals(2, stats.lines());
        assertEquals(1, stats.errorLines());
        assertEquals(30, stats.totalLatency());
        assertEquals(10, stats.maxLineBytes());
        assertEquals(Files.size(file), stats.bytesRead());
    }

    @Test
    void bufferMenorQueUmaLinhaProduceOMesmoResultado() throws IOException {
        StringBuilder content = new StringBuilder();
        for (int i = 0; i < 1_000; i++) {
            content.append(i).append(',').append(i % 3 == 0 ? "ERROR" : "INFO")
                    .append(',').append(i % 100).append('\n');
        }
        Path file = write(content.toString());

        Solution.Stats small = Solution.analyze(file, 16);
        Solution.Stats medium = Solution.analyze(file, 64);
        Solution.Stats large = Solution.analyze(file, 8192);

        assertEquals(small, medium);
        assertEquals(medium, large);
        assertEquals(1_000, small.lines());
        assertEquals(334, small.errorLines());
    }

    @Test
    void arquivoVazioRetornaZeros() throws IOException {
        Path file = write("");
        Solution.Stats stats = Solution.analyze(file, 16);

        assertEquals(0, stats.lines());
        assertEquals(0, stats.errorLines());
        assertEquals(0, stats.totalLatency());
        assertEquals(0, stats.maxLineBytes());
        assertEquals(0, stats.bytesRead());
    }

    @Test
    void linhasVaziasSaoIgnoradas() throws IOException {
        Path file = write("\n\n1,INFO,5\n\n");
        Solution.Stats stats = Solution.analyze(file, 16);

        assertEquals(1, stats.lines());
        assertEquals(5, stats.totalLatency());
    }

    @Test
    void arquivoGrandeProcessaSemMaterializarTodasAsLinhas() throws IOException {
        StringBuilder content = new StringBuilder(4_000_000);
        for (int i = 0; i < 100_000; i++) {
            content.append("req-").append(i).append(',')
                    .append(i % 10 == 0 ? "ERROR" : "INFO").append(',')
                    .append(i % 500).append('\n');
        }
        Path file = write(content.toString());

        Solution.Stats stats = Solution.analyze(file, 1024);

        assertEquals(100_000, stats.lines());
        assertEquals(10_000, stats.errorLines());
        assertEquals(Files.size(file), stats.bytesRead());
    }

    @Test
    void parametrosInvalidosFalham() {
        assertThrows(IllegalArgumentException.class,
                () -> Solution.analyze(null, 1024));
        assertThrows(IllegalArgumentException.class,
                () -> Solution.analyze(tempDir.resolve("x"), 15));
        assertThrows(IOException.class,
                () -> Solution.analyze(tempDir.resolve("nao-existe.csv"), 1024));
    }
}
